'use strict';
(function () {
  const listEl = document.getElementById('list');
  const emptyEl = document.getElementById('empty');
  const statusEl = document.getElementById('status');
  const form = document.getElementById('add-form');
  const input = document.getElementById('item-input');
  const addBtn = document.getElementById('add-button');

  let rendered = new Map(); // id -> {li, checkbox, textEl, bought}

  function setStatus(text, cls) {
    statusEl.textContent = text;
    statusEl.className = 'status' + (cls ? ' ' + cls : '');
  }

  function render(items) {
    const seen = new Set();
    let prev = null;
    for (const it of items) {
      seen.add(it.id);
      let row = rendered.get(it.id);
      if (!row) {
        const li = document.createElement('li');
        li.dataset.id = it.id;
        const cb = document.createElement('input');
        cb.type = 'checkbox';
        cb.setAttribute('aria-label', 'Bought: ' + it.text);
        cb.addEventListener('change', () => toggle(it.id, cb.checked));
        const span = document.createElement('span');
        span.className = 'text';
        const del = document.createElement('button');
        del.type = 'button';
        del.className = 'del';
        del.title = 'Remove';
        del.setAttribute('aria-label', 'Remove ' + it.text);
        del.textContent = '\u00d7';
        del.addEventListener('click', () => remove(it.id));
        li.appendChild(cb);
        li.appendChild(span);
        li.appendChild(del);
        row = { li, cb, span };
        rendered.set(it.id, row);
      }
      row.cb.checked = !!it.bought;
      row.span.textContent = it.text;
      row.li.classList.toggle('bought', !!it.bought);
      // keep order in sync
      const expectedNext = prev ? prev.nextSibling : listEl.firstChild;
      if (expectedNext !== row.li) listEl.insertBefore(row.li, expectedNext);
      prev = row.li;
    }
    for (const [id, row] of rendered) {
      if (!seen.has(id)) { row.li.remove(); rendered.delete(id); }
    }
    emptyEl.hidden = items.length > 0;
  }

  async function api(method, url, body) {
    const res = await fetch(url, {
      method,
      headers: body ? { 'Content-Type': 'application/json' } : undefined,
      body: body ? JSON.stringify(body) : undefined
    });
    if (!res.ok) throw new Error(method + ' ' + url + ' -> ' + res.status);
    return res.status === 204 ? null : res.json();
  }

  async function refresh() {
    try {
      const data = await api('GET', '/api/items');
      render(data.items);
      setStatus('Up to date — shared live with everyone', 'online');
    } catch (e) {
      setStatus('Offline — retrying…', 'offline');
    }
  }

  function toggle(id, bought) {
    api('PATCH', '/api/items/' + encodeURIComponent(id), { bought })
      .then(refresh).catch(() => { setStatus('Could not save change — retrying…', 'offline'); refresh(); });
  }
  function remove(id) {
    api('DELETE', '/api/items/' + encodeURIComponent(id))
      .then(refresh).catch(() => { setStatus('Could not remove item — retrying…', 'offline'); refresh(); });
  }

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const text = input.value.trim();
    if (!text) return;
    addBtn.disabled = true;
    try {
      await api('POST', '/api/items', { text });
      input.value = '';
      input.focus();
    } catch (err) {
      setStatus('Could not add item — try again', 'offline');
    } finally {
      addBtn.disabled = false;
      refresh();
    }
  });

  // Live updates: SSE for instant push, plus a 2s poll as a safety net.
  function connectSSE() {
    if (typeof EventSource === 'undefined') return;
    try {
      const es = new EventSource('/api/events');
      es.onmessage = (ev) => {
        try {
          const data = JSON.parse(ev.data);
          if (Array.isArray(data.items)) { render(data.items); setStatus('Live — shared with everyone', 'online'); }
        } catch (e) {}
      };
      es.onerror = () => { /* EventSource retries on its own; polling covers the gap */ };
    } catch (e) {}
  }

  refresh();
  connectSSE();
  setInterval(refresh, 2000);
  window.addEventListener('focus', refresh);
  document.addEventListener('visibilitychange', () => { if (!document.hidden) refresh(); });
})();
